/* Accordion Pill List Styling */
.sl-method-circles .sl-accordion-btn {
    background-color: var(--smartlearn-card-bg);
    border-color: var(--smartlearn-card-border) !important;
    color: var(--smartlearn-text);
    transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1);
    cursor: pointer;
    text-decoration: none;
}
.sl-method-circles .sl-accordion-btn:hover {
    border-color: var(--smartlearn-primary) !important;
    background-color: color-mix(in srgb, var(--smartlearn-primary) 8%, var(--smartlearn-card-bg));
    transform: translateX(4px);
}
.sl-method-circles .sl-accordion-icon {
    width: 38px;
    height: 38px;
    background-color: color-mix(in srgb, var(--smartlearn-text) 10%, transparent);
    color: var(--smartlearn-text);
    transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}
.sl-method-circles .sl-accordion-icon i {
    transition: transform 0.3s ease;
    font-size: 13px;
}
.sl-method-circles .sl-accordion-item.active .sl-accordion-btn {
    border-color: var(--smartlearn-primary) !important;
    background-color: color-mix(in srgb, var(--smartlearn-primary) 12%, var(--smartlearn-card-bg));
}
.sl-method-circles .sl-accordion-item.active .sl-accordion-icon {
    background-color: var(--smartlearn-primary);
    color: #FFFFFF !important;
    transform: rotate(90deg);
}
.sl-method-circles .sl-accordion-body-wrapper {
    max-height: 0;
    overflow: hidden;
    transition: max-height 0.4s cubic-bezier(0.16, 1, 0.3, 1), opacity 0.3s ease;
    opacity: 0;
}
.sl-method-circles .sl-accordion-item.active .sl-accordion-body-wrapper {
    max-height: 500px;
    opacity: 1;
}
.sl-method-circles .tracking-wider {
    letter-spacing: 0.05em;
    font-size: 0.95rem;
}
.sl-method-circles .sl-badge-eyebrow {
    background-color: color-mix(in srgb, var(--smartlearn-primary) 15%, transparent);
    color: var(--smartlearn-primary);
    font-size: 0.85rem;
    font-weight: 700;
    letter-spacing: 0.08em;
}
.sl-method-circles .sl-method-title {
    line-height: 1.15;
    letter-spacing: -0.03em;
    color: var(--smartlearn-text);
}
.sl-method-circles .sl-orbs-stage {
    min-height: 280px;
    background-color: var(--smartlearn-card-bg);
    border-color: var(--smartlearn-card-border) !important;
}
.sl-method-circles .sl-ambient-glow {
    width: 200px;
    height: 200px;
    background: radial-gradient(circle, color-mix(in srgb, var(--smartlearn-primary) 30%, transparent) 0%, transparent 70%);
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    pointer-events: none;
}
.sl-method-circles .sl-orb {
    background-color: color-mix(in srgb, var(--smartlearn-card-bg) 80%, var(--smartlearn-bg));
    border: 1.5px solid var(--smartlearn-card-border);
    color: var(--smartlearn-text);
    box-shadow: 0 10px 25px -5px rgba(0,0,0,0.08);
    transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1);
    cursor: pointer;
}
.sl-method-circles .sl-orb:hover {
    transform: scale(1.1) translateY(-6px) !important;
    border-color: var(--smartlearn-primary);
    background-color: color-mix(in srgb, var(--smartlearn-primary) 15%, var(--smartlearn-card-bg));
    box-shadow: 0 15px 30px -5px color-mix(in srgb, var(--smartlearn-primary) 25%, transparent);
}
.sl-method-circles .sl-orb-lg {
    width: 135px;
    height: 135px;
    background-color: color-mix(in srgb, var(--smartlearn-primary) 12%, var(--smartlearn-card-bg));
    border-color: color-mix(in srgb, var(--smartlearn-primary) 40%, var(--smartlearn-card-border));
}
.sl-method-circles .sl-orb-lg i {
    color: var(--smartlearn-primary);
}
.sl-method-circles .sl-orb-md {
    width: 110px;
    height: 110px;
}
.sl-method-circles .sl-orb-sm {
    width: 95px;
    height: 95px;
}

/* Floating Keyframe Animations */
.sl-method-circles .sl-orb-float-1 {
    animation: slFloat1 5s ease-in-out infinite alternate;
}
.sl-method-circles .sl-orb-float-2 {
    animation: slFloat2 6s ease-in-out infinite alternate;
}
.sl-method-circles .sl-orb-float-3 {
    animation: slFloat3 4.5s ease-in-out infinite alternate;
}
.sl-method-circles .sl-orb-float-4 {
    animation: slFloat4 5.5s ease-in-out infinite alternate;
}
.sl-method-circles .sl-orb-float-5 {
    animation: slFloat5 6.5s ease-in-out infinite alternate;
}

@keyframes slFloat1 {
    0% { transform: translateY(0) rotate(0deg); }
    100% { transform: translateY(-10px) rotate(2deg); }
}
@keyframes slFloat2 {
    0% { transform: translateY(0) scale(1); }
    100% { transform: translateY(-14px) scale(1.03); }
}
@keyframes slFloat3 {
    0% { transform: translateY(0); }
    100% { transform: translateY(-8px) translateX(4px); }
}
@keyframes slFloat4 {
    0% { transform: translateY(0); }
    100% { transform: translateY(-12px) translateX(-4px); }
}
@keyframes slFloat5 {
    0% { transform: translateY(0); }
    100% { transform: translateY(-10px); }
}

js:
(function() {
    const root = document.querySelector('.sl-method-circles');
    if (!root) return;

    const accordionItems = root.querySelectorAll('.sl-accordion-item');

    accordionItems.forEach(item => {
        const btn = item.querySelector('.sl-accordion-header');
        if (!btn) return;

        btn.addEventListener('click', (e) => {
            if (document.body.classList.contains('sl-editor-mode')) return;
            e.preventDefault();

            const isOpen = item.classList.contains('active');

            // Close other items (exclusive accordion)
            accordionItems.forEach(other => {
                if (other !== item) other.classList.remove('active');
            });

            // Toggle current item
            if (isOpen) {
                item.classList.remove('active');
            } else {
                item.classList.add('active');
            }
        });
    });
})();
